mapper.select:
select t1.id, t1.res_name as name, t1.res_path as path, t1.icon as icon, t1.res_level, t1.order_no, t1.parent_id as pid, t1.res_type as type, t1.hidden, t1.res_mode, t1.remark, t1.res_url as url, t1.key_name, t1.keep_alive, t1.expand, t1.business_expand from la_resources t1 left join la_applications t2 on t2.id = t1.application where t1.res_type != 3 and t1.res_mode = #{query.mode}
and (t1.application is null or t2.standalone = 0)
and t1.application = #{query.application}
and t1.id in ( select distinct t.resource_id from la_role_resources t where t.authority in #{item} )
and t1.res_level = #{query.level}
and t1.parent_keys like concat(#{query.parentId}, '%')
and t1.res_name like concat('%', #{query.name}, '%')
order by t1.res_level, t1.parent_id, t1.order_no
